  cr=await rpc(a,'create_room',dict(p_name='V2 evidence validation',p_format='IPL',p_settings=s,p_nickname='Host',p_team='Evidence Royals',p_color='#f4c34d'));rid=cr['room_id'];await rpc(g,'join_room',dict(p_code=cr['code'],p_nickname='Guest',p_team='Evidence Kings',p_color='#29d7ee'))
  ids=await a.evaluate('''async()=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return (await supabase.from('players').select('id').eq('format','IPL').limit(4)).data.map(p=>p.id);}''');await rpc(a,'set_pool',dict(p_room=rid,p_player_ids=ids));await rpc(a,'start_review',dict(p_room=rid));await rpc(a,'host_control',dict(p_room=rid,p_action='skip_review'));await rpc(a,'tick',dict(p_room=rid));await rpc(a,'host_control',dict(p_room=rid,p_action='pause'));await a.goto(U+'/room/'+rid);await g.goto(U+'/room/'+rid);await a.locator('.auction-broadcast').wait_for();await g.locator('.auction-broadcast').wait_for()
