  denied=await g.evaluate('''async()=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return Promise.all(['rooms','room_players'].map(async t=>{const r=await supabase.from(t).select('*');return !!r.error;}));}''');assert denied==[True,True]
  assert await g.locator('.upcoming-player').count()==0;assert await g.get_by_text('Remaining purse',exact=True).is_visible();await g.get_by_role('button',name='Explain maximum affordable bid').click();await g.get_by_text('Conservative server reserve',exact=True).wait_for();await g.screenshot(path='/tmp/browser/random-order/budget-explanation.png');await g.keyboard.press('Escape');await g.screenshot(path='/tmp/browser/random-order/surprise-mobile.png');assert not await g.evaluate('document.documentElement.scrollWidth>innerWidth');print('PASS member raw-table denial, zero future ordinals, mystery, sticky purse/max, 390px')
  await rpc(a,'host_control',dict(p_room=rid,p_action='resume'));cur=next(p for p in proj['pool'] if p['id']==proj['room']['current_rp']);await rpc(a,'place_bid',dict(p_room=rid,p_amount=cur['player']['base_price']));await a.get_by_role('region',name='Last sold').wait_for(timeout=15000);await rpc(a,'host_control',dict(p_room=rid,p_action='pause'));await a.wait_for_timeout(3500);await a.reload();await a.get_by_role('region',name='Last sold').wait_for();assert await a.locator('.sale-reveal').count()==0;print('PASS persistent sold on reload without replay')
  await rpc(a,'host_control',dict(p_room=rid,p_action='undo'));await a.wait_for_timeout(1200);assert await a.get_by_role('region',name='Last sold').count()==0;print('PASS undo clears last sold')
  await rpc(a,'host_control',dict(p_room=rid,p_action='end'));await rpc(a,'host_control',dict(p_room=rid,p_action='results'));await a.get_by_text('No valid-XI champion',exact=True).wait_for(timeout=30000);await g.get_by_text('No valid-XI champion',exact=True).wait_for(timeout=30000);await a.screenshot(path='/tmp/browser/random-order/v2-results.png');await g.screenshot(path='/tmp/browser/random-order/v2-results-mobile.png');print('PASS cross-client canonical empty/ineligible V2 results')
  stored=await a.evaluate('''async id=>{const {supabase}=await import('/src/integrations/supabase/client.ts');return (await supabase.from('room_evaluations').select('version,snapshot_id,result').eq('room_id',id).single()).data;}''',rid);assert stored and stored['version']=='v2.0' and stored['snapshot_id'];print('PASS persisted frozen snapshot results');assert not errs,errs;await b.close()
